<?php
namespace Tests\Feature;use App\Jobs\{GenerateMediaExport,ProcessMediaAsset};use App\Models\{Folder,Group,Photo,UploadBatch,User};use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Http\UploadedFile;use Illuminate\Support\Facades\{Hash,Queue,Storage};use Tests\TestCase;
class BackgroundProcessingTest extends TestCase {use RefreshDatabase;protected function setUp():void{parent::setUp();config(['media.disk'=>'private_local','queue.default'=>'sync']);Storage::fake('private_local');}private function owner(string$email):array{$u=User::create(['name'=>'Owner','email'=>$email,'password'=>Hash::make('x'),'status'=>'active','account_type'=>'photographer','plan'=>'basic']);$g=Group::create(['name'=>'Event','creator_id'=>$u->id]);$g->members()->attach($u->id,['role'=>'admin','membership_status'=>'active','access_type'=>'full_access']);return[$u,$g];}
 public function test_original_is_stored_and_processing_is_dispatched():void{Queue::fake();[$u,$g]=$this->owner('owner@example.com');$this->actingAs($u)->postJson(route('photos.store',$g),['photos'=>[UploadedFile::fake()->image('one.jpg')]])->assertOk()->assertJsonStructure(['upload_reference','status','display_status','message'])->assertJsonPath('display_status','Preparing')->assertJsonMissing(['batch_uuid']);$batch=UploadBatch::firstOrFail();$this->assertSame('queued',$batch->fresh()->state);$asset=$batch->files()->firstOrFail()->asset;Storage::disk('private_local')->assertExists($asset->original_object_key);$this->assertCount(1,$asset->variants);Queue::assertPushed(ProcessMediaAsset::class,fn($job)=>$job->queue==='media-high');}
 public function test_database_queue_connection_is_configured_for_after_commit_processing():void{$this->assertSame('database',config('queue.connections.database.driver'));$this->assertTrue(config('queue.connections.database.after_commit'));$this->assertSame('jobs',config('queue.connections.database.table'));}
 public function test_media_worker_queue_list_covers_every_dispatched_queue():void{$this->assertEqualsCanonicalizing(['media-high','media-default','exports','maintenance'],config('horizon.defaults.supervisor-1.queue'));}
 public function test_status_endpoint_presents_friendly_upload_progress():void{[$owner,$group]=$this->owner('friendly-status@example.com');$batch=UploadBatch::create(['uuid'=>(string)\Illuminate\Support\Str::uuid(),'group_id'=>$group->id,'user_id'=>$owner->id,'state'=>'queued','total_files'=>2,'pending_files'=>2]);$batch->files()->createMany([['client_filename'=>'one.jpg','state'=>'queued'],['client_filename'=>'two.jpg','state'=>'queued']]);$this->actingAs($owner)->getJson(route('processing.show',$batch))->assertOk()->assertJsonPath('status','queued')->assertJsonPath('display_status','Preparing')->assertJsonPath('files.0.display_status','Preparing')->assertJsonPath('gallery_url',route('groups.gallery',$group))->assertJsonPath('progress_percentage',0);}
 public function test_photo_selection_ui_is_accessible_and_does_not_open_viewer():void{$selector=file_get_contents(resource_path('js/Components/PhotoSelector.vue'));$gallery=file_get_contents(resource_path('js/Pages/Groups/Show.vue'));$progress=file_get_contents(resource_path('js/Pages/Groups/Operations.vue'));$this->assertStringContainsString('type="checkbox"',$selector);$this->assertStringContainsString('class="peer sr-only"',$selector);$this->assertStringContainsString('@click.stop',$selector);$this->assertStringContainsString('<svg v-if="checked"',$selector);$this->assertStringContainsString('<PhotoSelector',$gallery);$this->assertStringContainsString('sessionStorage',$gallery);$this->assertStringContainsString("{{upload.display_status}}",$progress);$this->assertStringNotContainsString('{{upload.state',$progress);$this->assertStringNotContainsString('Upload batches',$progress);$this->assertStringNotContainsString('queued files',$progress);}
 public function test_progress_is_not_visible_across_accounts():void{[$owner,$group]=$this->owner('owner@example.com');[$other]=$this->owner('other@example.com');$batch=UploadBatch::create(['uuid'=>(string)\Illuminate\Support\Str::uuid(),'group_id'=>$group->id,'user_id'=>$owner->id,'total_files'=>1]);$this->actingAs($other)->getJson(route('processing.show',$batch))->assertForbidden();}
 public function test_cancel_and_retry_require_owned_batch():void{[$owner,$group]=$this->owner('owner@example.com');$batch=UploadBatch::create(['uuid'=>(string)\Illuminate\Support\Str::uuid(),'group_id'=>$group->id,'user_id'=>$owner->id,'total_files'=>1]);$this->actingAs($owner)->postJson(route('processing.cancel',$batch))->assertOk()->assertJson(['state'=>'cancelled']);$this->postJson(route('processing.retry',$batch))->assertStatus(409);}
 public function test_upload_inherits_route_group_and_starts_in_all_photos():void{Queue::fake();[$owner,$group]=$this->owner('folder-owner@example.com');$folder=Folder::create(['group_id'=>$group->id,'name'=>'Ceremony']);$this->actingAs($owner)->postJson(route('photos.store',$group),['folder_id'=>$folder->id,'group_id'=>999999,'studio_id'=>999999,'photos'=>[UploadedFile::fake()->image('portrait.jpg',800,1200)]])->assertOk()->assertJsonPath('folder_id',null);$photo=$group->photos()->firstOrFail();$this->assertNull($photo->folder_id);$this->assertSame($group->id,$photo->group_id);$this->assertSame($group->id,$photo->mediaAsset->group_id);Queue::assertPushed(ProcessMediaAsset::class,1);}
 public function test_foreign_folder_input_is_ignored_and_cannot_reassign_upload():void{Queue::fake();[$owner,$group]=$this->owner('cross-folder-owner@example.com');[, $other]=$this->owner('other-folder-owner@example.com');$foreign=Folder::create(['group_id'=>$other->id,'name'=>'Foreign']);$this->actingAs($owner)->postJson(route('photos.store',$group),['folder_id'=>$foreign->id,'group_id'=>$other->id,'photos'=>[UploadedFile::fake()->image('safe.jpg')]])->assertOk();$photo=$group->photos()->firstOrFail();$this->assertNull($photo->folder_id);$this->assertSame($group->id,$photo->group_id);$this->assertDatabaseMissing('photos',['group_id'=>$other->id,'original_filename'=>'safe.jpg']);}
 public function test_bulk_move_rejects_foreign_folder_and_photo_ids():void{[$owner,$group]=$this->owner('move-owner@example.com');$other=Group::create(['name'=>'Other','creator_id'=>$owner->id]);$foreignFolder=Folder::create(['group_id'=>$other->id,'name'=>'Foreign']);$photo=Photo::create(['group_id'=>$group->id,'uploader_id'=>$owner->id,'filename'=>'one.jpg','original_filename'=>'one.jpg','path'=>'private/one.jpg']);$foreignPhoto=Photo::create(['group_id'=>$other->id,'uploader_id'=>$owner->id,'filename'=>'two.jpg','original_filename'=>'two.jpg','path'=>'private/two.jpg']);$this->actingAs($owner)->postJson(route('photos.bulk-folder',$group),['photo_ids'=>[$photo->id],'folder_id'=>$foreignFolder->id])->assertNotFound();$this->postJson(route('photos.bulk-folder',$group),['photo_ids'=>[$photo->id,$foreignPhoto->id],'folder_id'=>null])->assertStatus(422);$this->assertNull($photo->fresh()->folder_id);}
 public function test_export_rejects_cross_group_ids_and_requires_download_permission():void{Queue::fake();[$owner,$group]=$this->owner('export-owner@example.com');$group->update(['downloads_enabled'=>true]);$other=Group::create(['name'=>'Other','creator_id'=>$owner->id,'downloads_enabled'=>true]);$photo=Photo::create(['group_id'=>$group->id,'uploader_id'=>$owner->id,'filename'=>'one.jpg','original_filename'=>'one.jpg','path'=>'private/one.jpg']);$foreign=Photo::create(['group_id'=>$other->id,'uploader_id'=>$owner->id,'filename'=>'two.jpg','original_filename'=>'two.jpg','path'=>'private/two.jpg']);$this->actingAs($owner)->postJson(route('exports.store',$group),['photo_ids'=>[$photo->id,$foreign->id]])->assertStatus(422);$this->assertDatabaseCount('media_exports',0);$this->postJson(route('exports.store',$group),['photo_ids'=>[$photo->id]])->assertStatus(202);Queue::assertPushed(GenerateMediaExport::class,1);$group->update(['downloads_enabled'=>false]);$this->postJson(route('exports.store',$group),['photo_ids'=>[$photo->id]])->assertForbidden();}
}
